    public int maxBeauty(int[] nums, int k) {
        int n = nums.length;
        int[] sortedNums = new int[n + 1];
        for (int i = 0; i < n; i++) {
            sortedNums[i + 1] = nums[i];
        }
        Arrays.sort(sortedNums);

        int[] prefixMax = new int[n + 1];
